/*
 * A081261  Start with a(1)=4; apply 4 -> 665, 5 -> 56665, 6 -> 566665;
 *          iterate.
 * https://oeis.org/A081261
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence a(n) is generated by starting with the digit 4 and
   iteratively expanding each digit according to the morphism:
       4 → 665
       5 → 56665
       6 → 566665
   The digits produced by each expansion are appended to the end of the
   current sequence.  a(1) = 4; for n ≥ 2, a(n) is the n‑th digit
   produced by this process.  The function returns the value as a
   seq_t type. */
#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n == (idx_t)0)
        return (seq_t)0;                 /* undefined for offset 0 */
    if (n == (idx_t)1)
        return (seq_t)4;

    size_t cap = 128;
    char *seq = (char *)malloc(cap);
    if (!seq)
        return (seq_t)0;                 /* allocation failure */

    size_t len = 1;
    seq[0] = '4';                         /* a(1) */
    size_t i = 0;                         /* index of next digit to expand */

    while (len < (size_t)n) {
        char c = seq[i];
        switch (c) {
            case '4':
                if (len + 3 > cap) {
                    cap <<= 1;
                    seq = (char *)realloc(seq, cap);
                }
                seq[len++] = '6';
                seq[len++] = '6';
                seq[len++] = '5';
                break;
            case '5':
                if (len + 5 > cap) {
                    cap <<= 1;
                    seq = (char *)realloc(seq, cap);
                }
                seq[len++] = '5';
                seq[len++] = '6';
                seq[len++] = '6';
                seq[len++] = '6';
                seq[len++] = '5';
                break;
            case '6':
                if (len + 6 > cap) {
                    cap <<= 1;
                    seq = (char *)realloc(seq, cap);
                }
                seq[len++] = '5';
                seq[len++] = '6';
                seq[len++] = '6';
                seq[len++] = '6';
                seq[len++] = '6';
                seq[len++] = '5';
                break;
            default:
                break; /* should not occur */
        }
        ++i;
    }

    char result = seq[n - 1];
    free(seq);
    return (seq_t)(result - '0');
}
